package dev.kelmagic.block;
import dev.kelmagic.*;import dev.kelmagic.entity.RedMage;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.shapes.*;
public final class MageThroneBlock extends DoublePlantBlock {
 public static final DirectionProperty FACING=HorizontalDirectionalBlock.FACING;
 public MageThroneBlock(BlockBehaviour.Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(HALF,DoubleBlockHalf.LOWER).setValue(FACING,Direction.NORTH));}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){super.createBlockStateDefinition(b);b.add(FACING);}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){var s=super.getStateForPlacement(c);return s==null?null:s.setValue(FACING,c.getHorizontalDirection().getOpposite());}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,LivingEntity e,ItemStack i){l.setBlock(p.above(),s.setValue(HALF,DoubleBlockHalf.UPPER),3);}
 @Override protected boolean canSurvive(BlockState s,LevelReader l,BlockPos p){if(s.getValue(HALF)==DoubleBlockHalf.UPPER)return l.getBlockState(p.below()).is(this)&&l.getBlockState(p.below()).getValue(HALF)==DoubleBlockHalf.LOWER;return l.getBlockState(p.below()).isFaceSturdy(l,p.below(),Direction.UP);}
 public static BlockPos base(BlockState s,BlockPos p){return s.getValue(HALF)==DoubleBlockHalf.UPPER?p.below():p;}
 private static final VoxelShape[] LOWER_SHAPES=new VoxelShape[4],UPPER_SHAPES=new VoxelShape[4];
 static{VoxelShape low=Shapes.or(Block.box(0,0,0,16,2,18),Block.box(1,2,1,15,7,17),Block.box(2,6.7,5.9,14,9,16.5),Block.box(0,2,1,2,15.5,17),Block.box(14,2,1,16,15.5,17),Block.box(0,9,16.5,16,16,18));VoxelShape up=Block.box(0,0,16.5,16,16,18);for(int i=0;i<4;i++){LOWER_SHAPES[i]=rotateShape(low,i);UPPER_SHAPES[i]=rotateShape(up,i);}}
 private static VoxelShape rotateShape(VoxelShape s,int turns){var out=Shapes.empty();for(var box:s.toAabbs()){double x0=box.minX,x1=box.maxX,z0=box.minZ,z1=box.maxZ;for(int i=0;i<turns;i++){double nx0=1-z1,nx1=1-z0;z0=x0;z1=x1;x0=nx0;x1=nx1;}out=Shapes.or(out,Shapes.box(x0,box.minY,z0,x1,box.maxY,z1));}return out;}
 @Override protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){int n=s.getValue(FACING)==Direction.NORTH?0:s.getValue(FACING)==Direction.EAST?1:s.getValue(FACING)==Direction.SOUTH?2:3;return (s.getValue(HALF)==DoubleBlockHalf.LOWER?LOWER_SHAPES:UPPER_SHAPES)[n];}
 @Override protected VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return getShape(s,l,p,c);}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player user,BlockHitResult h){if(user.isShiftKeyDown())return InteractionResult.PASS;if(l.isClientSide)return InteractionResult.SUCCESS;var pos=base(s,p);if(!l.getBlockState(pos).is(this)||!l.getBlockState(pos.above()).is(this))return InteractionResult.FAIL;
 boolean occupied=!l.getEntitiesOfClass(RedMage.class,new net.minecraft.world.phys.AABB(pos).inflate(3),e->e.isAlive()&&e.throne().filter(pos::equals).isPresent()).isEmpty();if(occupied){user.displayClientMessage(net.minecraft.network.chat.Component.literal("Трон занят чародейкой."),true);return InteractionResult.CONSUME;}
 var seats=l.getEntitiesOfClass(dev.kelmagic.entity.ThroneSeat.class,new net.minecraft.world.phys.AABB(pos).inflate(2),e->e.home().equals(pos));if(seats.stream().anyMatch(e->!e.getPassengers().isEmpty()))return InteractionResult.CONSUME;if(user.isPassenger())return InteractionResult.PASS;
 var seat=seats.isEmpty()?MagicCreatures.THRONE_SEAT.get().create(l):seats.getFirst();if(seats.isEmpty()){seat.bind(pos);l.addFreshEntity(seat);}if(!user.startRiding(seat,true)){seat.discard();return InteractionResult.FAIL;}float yaw=l.getBlockState(pos).getValue(FACING).toYRot();user.setYRot(yaw);user.setXRot(0);if(user instanceof net.minecraft.server.level.ServerPlayer sp)sp.connection.teleport(seat.getX(),seat.getY(),seat.getZ(),yaw,0);return InteractionResult.CONSUME;
 }
 @Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player user){var low=base(s,p);if(!l.isClientSide){if(s.getValue(HALF)==DoubleBlockHalf.UPPER&&l.getBlockState(low).is(this)){if(!user.isCreative())Block.dropResources(l.getBlockState(low),l,low,null,user,user.getMainHandItem());l.setBlock(low,Blocks.AIR.defaultBlockState(),34);}else if(l.getBlockState(low.above()).is(this))l.setBlock(low.above(),Blocks.AIR.defaultBlockState(),34);}return s;}
 @Override public void playerDestroy(Level l,Player user,BlockPos p,BlockState s,net.minecraft.world.level.block.entity.BlockEntity be,ItemStack tool){user.awardStat(net.minecraft.stats.Stats.BLOCK_MINED.get(this));user.causeFoodExhaustion(.005f);Block.dropResources(s,l,p,be,user,tool);}
 @Override protected BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}
 @Override protected BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
}
